CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, google_sub text UNIQUE NOT NULL, email text NOT NULL, name text NOT NULL, avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session(sid varchar NOT NULL PRIMARY KEY,sess json NOT NULL,expire timestamp(6) NOT NULL);
CREATE INDEX IF NOT EXISTS session_expire ON session(expire);
CREATE TABLE IF NOT EXISTS sender_templates(id uuid PRIMARY KEY, name text NOT NULL,email text NOT NULL UNIQUE,credentials text NOT NULL);
ALTER TABLE sender_templates ADD COLUMN IF NOT EXISTS default_order int;
CREATE TABLE IF NOT EXISTS senders(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),template_id uuid NOT NULL REFERENCES sender_templates(id),name text NOT NULL,email text NOT NULL,credentials text NOT NULL,next_allowed_at timestamptz NOT NULL DEFAULT now(),hour_start timestamptz NOT NULL DEFAULT date_trunc('hour',now()),hour_count int NOT NULL DEFAULT 0,hourly_limit int NOT NULL DEFAULT 200, UNIQUE(user_id,template_id));
CREATE TABLE IF NOT EXISTS campaigns(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),sender_id uuid NOT NULL REFERENCES senders(id),subject text NOT NULL,body text NOT NULL,start_at timestamptz NOT NULL,delay_ms int NOT NULL,hourly_limit int NOT NULL,hour_start timestamptz NOT NULL DEFAULT date_trunc('hour',now()),hour_count int NOT NULL DEFAULT 0,next_allowed_at timestamptz NOT NULL DEFAULT now(),idempotency_key text NOT NULL,request_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS emails(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),sender_id uuid NOT NULL REFERENCES senders(id),campaign_id uuid NOT NULL REFERENCES campaigns(id),recipient text NOT NULL,sequence int NOT NULL,subject text NOT NULL,body text NOT NULL,scheduled_at timestamptz NOT NULL,next_attempt_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','sending','sent','failed','unknown')),reason text,attempts int NOT NULL DEFAULT 0,claimed_at timestamptz,sent_at timestamptz,message_id text,preview_url text,error text,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(campaign_id,recipient));
CREATE INDEX IF NOT EXISTS emails_owner_pending ON emails(user_id,status,next_attempt_at,id);
CREATE INDEX IF NOT EXISTS senders_template ON senders(template_id);
ALTER TABLE senders ADD COLUMN IF NOT EXISTS is_hidden boolean NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS emails_owner_sent ON emails(user_id,status,sent_at,id);
CREATE TABLE IF NOT EXISTS outbox(id uuid PRIMARY KEY,kind text NOT NULL,aggregate_id uuid NOT NULL,version int NOT NULL DEFAULT 1,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,aggregate_id,version));
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(created_at) WHERE published_at IS NULL;
CREATE TABLE IF NOT EXISTS slack_connections(user_id uuid PRIMARY KEY REFERENCES users(id),team_id text NOT NULL,team_name text,channel_name text,credentials text NOT NULL,generation uuid NOT NULL,connected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_events(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),sender_id uuid NOT NULL REFERENCES senders(id),hour_start timestamptz NOT NULL,limit_value int NOT NULL,notified_at timestamptz,state text NOT NULL DEFAULT 'pending',error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(sender_id,hour_start));
